using System;
#pragma warning disable IDE0130
namespace PayrollEngine.Client.Scripting.Function;
#pragma warning restore IDE0130

public partial class WageTypeValueFunction
{
    // WT 1250 — §132(f) Commuter Transit Benefit (Pre-Tax)
    // IRC §132(f): employer-provided transit passes/vanpool are FIT-exempt, FICA-exempt,
    // and SIT-exempt for most states (NY, NJ, MA, WA, CT conform; CA does NOT).
    // Reads Apex.TransitBenefitMonthly (Money/CalendarPeriod) directly as per-period amount.
    // 2026 monthly exclusion limit: $315 (IRS Rev. Proc. 2025-20).
    // Returns negative value subtracted from FIT and FICA taxable wages
    // via WT 1250 extensibility slot in USComputeFitTaxable / USComputeFicaTaxable.
    [ActionParameter("transitField", "CaseField Apex.TransitBenefitMonthly — pre-tax transit benefit per period")]
    [WageTypeValueAction("USCalculateTransitBenefit",
        "Pre-tax §132(f) commuter transit benefit. Reads Apex.TransitBenefitMonthly and returns "
        + "negative value. Reduces FIT and FICA taxable wages via WT 1250 extensibility slot. "
        + "Returns null when field is zero or not set.")]
    public ActionValue USCalculateTransitBenefit(string transitField)
    {
        var amount = GetCaseValue<decimal?>(transitField) ?? 0m;
        if (amount <= 0m) return null;
        return -Math.Round(amount, 2);
    }

    // WT 1260 — WFH Equipment Stipend (Taxable Fringe Benefit)
    // Fully taxable — included in FIT, FICA, SIT, FUTA.
    // No federal or state exclusion applies to a flat WFH stipend
    // (IRC §62(a)(2)(A) accountable plan rules not met for flat payments).
    // Reads Apex.WFHStipend (Money/CalendarPeriod) and returns positive value.
    [ActionParameter("stipendField", "CaseField Apex.WFHStipend — per-period WFH stipend amount")]
    [WageTypeValueAction("USCalculateWFHStipend",
        "Returns WFH equipment stipend as taxable gross income. Reads Apex.WFHStipend field directly. "
        + "Returns null when not set or zero. Positive value adds to GrossWages.")]
    public ActionValue USCalculateWFHStipend(string stipendField)
    {
        var amount = GetCaseValue<decimal?>(stipendField) ?? 0m;
        if (amount <= 0m) return null;
        return Math.Round(amount, 2);
    }
}
